import os
import json
from google.cloud import documentai_v1 as documentai

def normalize_expense(payload, config=None):
    config = config or {}
    client = documentai.DocumentProcessorServiceClient()
    processor_name = f"projects/{config.get('project_id', os.getenv('GOOGLE_CLOUD_PROJECT'))}/locations/{config.get('location', 'us')}/processors/{config.get('processor_id', os.getenv('DOCUMENT_AI_PROCESSOR_ID', 'your-processor-id'))}"

    # Initialize request
    request = documentai.ProcessRequest(
        name=processor_name,
        raw_document=documentai.RawDocument(
            content=payload,
            mime_type="application/pdf"  # or "image/png", "image/jpeg"
        )
    )

    # Process document
    result = client.process_document(request=request)

    # Normalize extracted fields into standard schema
    normalized = {
        "vendor": "",
        "date": "",
        "amount": 0.0,
        "currency": "USD",
        "category": "",
        "line_items": []
    }

    document = result.document
    for entity in document.entities:
        if entity.type_ == "vendor_name":
            normalized["vendor"] = entity.mention_text
        elif entity.type_ == "transaction_date":
            normalized["date"] = entity.mention_text
        elif entity.type_ == "total_amount":
            normalized["amount"] = float(entity.mention_text.replace(",", ""))
        elif entity.type_ == "currency":
            normalized["currency"] = entity.mention_text
        elif entity.type_ == "line_item":
            line_item = {
                "description": "",
                "quantity": 1,
                "unit_price": 0.0,
                "amount": 0.0
            }
            for prop in entity.properties:
                if prop.type_ == "line_item_description":
                    line_item["description"] = prop.mention_text
                elif prop.type_ == "line_item_quantity":
                    line_item["quantity"] = int(prop.mention_text)
                elif prop.type_ == "line_item_unit_price":
                    line_item["unit_price"] = float(prop.mention_text.replace(",", ""))
                elif prop.type_ == "line_item_amount":
                    line_item["amount"] = float(prop.mention_text.replace(",", ""))
            normalized["line_items"].append(line_item)

    return normalized
